import{X as e,Z as t,at as n,i as r,nt as i,tt as a}from"./client-B8Z9j2-W.js";import{c as o}from"./page-header-1nVmxNus.js";import{i as s}from"./triangle-alert-DHcGtn6V.js";import{a as c,n as l,o as u,r as d,t as f}from"./select-C_gth22X.js";import{t as p}from"./spinner-Dpx8CxHH.js";import{a as m,i as h,n as g,o as _,r as v,t as y}from"./dialog-CUS0TYd_.js";import{n as b}from"./context-IfoozZSV.js";import{t as x}from"./field-C-T3C0-a.js";import{it as S,nt as C}from"./index-_YdXS2pE.js";import{n as w}from"./auth-boundary-CVSu0Rjm.js";var T=n(i(),1);s(`providers`,{en:{title:`Providers`,subtitle:`The credential a session launches with. Register it once; the engine seals it and hands it to the agent at launch.`,nav:`Providers`,add:`Add provider`,empty:{title:`No provider registered yet`,description:`A session cannot launch without a credential. Add the API key of Anthropic, OpenAI or xAI — or any OpenAI-compatible endpoint — and the engine seals it and uses it at launch. The key is never shown again.`,action:`Add your first provider`},emptyFiltered:{title:`No provider matches this filter`,description:`Clear the filter to see every registered provider.`,action:`Show all`},forbidden:{title:`You cannot read the providers of this tenant`,description:`Reading registered providers needs sessions:provider:read. Ask an administrator of this tenant for it.`},columns:{name:`Name`,kind:`Kind`,key:`Key`,state:`State`,connection:`Connection`},kinds:{anthropic:`Anthropic`,openai:`OpenAI`,xai:`xAI`,openai_compatible:`OpenAI-compatible`},kindHints:{anthropic:`Claude Code. Injects ANTHROPIC_API_KEY.`,openai:`Codex. Injects OPENAI_API_KEY.`,xai:`Grok. Injects XAI_API_KEY.`,openai_compatible:`Any OpenAI-shaped endpoint. Injects OPENAI_API_KEY and OPENAI_BASE_URL; the endpoint is required.`},states:{active:`Active`,revoked:`Revoked`},probe:{never:`Not tested`,ok:`Accepted`,refused:`Refused`,unreachable:`Unreachable`,neverHint:`Nobody has tested this credential. Registering it is not evidence that it works.`,okHint:`The provider answered and accepted this credential.`,refusedHint:`The provider answered and rejected this credential. Rotate it.`,unreachableHint:`The endpoint did not answer. This says nothing about the credential.`,models:`{{n}} models`,latency:`{{ms}} ms`,at:`Tested {{when}}`},actions:{test:`Test connection`,testing:`Testing…`,rotate:`Rotate key`,revoke:`Revoke`,details:`Details`},create:{title:`Add a provider`,description:`The engine seals the key and never returns it. You will see a four-character hint and nothing more.`,kind:`Provider`,kindPlaceholder:`Choose a provider`,name:`Name`,nameHint:`Your own name for this credential. It is what a picker shows.`,namePlaceholder:`Anthropic (production)`,baseURL:`Endpoint`,baseURLHint:`Leave empty for the provider's official endpoint. Must be https.`,baseURLPlaceholder:`https://llm.example.com`,apiKey:`API key`,apiKeyHint:`Sent once, sealed by the engine, never returned to this browser.`,apiKeyPlaceholder:`Paste the key`,submit:`Add provider`,submitting:`Sealing…`,cancel:`Cancel`,success:`Provider registered. Test the connection to confirm it works.`,testNext:`Test connection now`},rotate:{title:`Rotate this provider's key`,description:`The new key replaces the old one under the same reference, so every profile bound to it keeps working. A session already running keeps the credential it started with.`,verdictCleared:`The previous connection test is cleared: a verdict measured on a credential that no longer exists is not evidence about the one replacing it.`,submit:`Rotate key`,submitting:`Sealing…`,success:`Key rotated. Test the connection to confirm the new one works.`},revoke:{title:`Revoke this provider`,description:`This destroys the sealed credential. It cannot be undone for this reference.`,consequence:`Every provider profile bound to it will refuse to launch, naming this provider. The credential is not revoked at the provider itself: do that in their own console.`,confirm:`Revoke`,success:`Provider revoked and its sealed credential destroyed.`},detail:{title:`Provider`,reference:`Reference`,endpoint:`Endpoint`,officialEndpoint:`The provider's official endpoint`,created:`Registered`,revoked:`Revoked`,models:`Models the last test listed`,noModels:`No model list yet. Test the connection.`,close:`Close`},vaultUnavailable:{title:`This deployment cannot store a provider credential`,description:`No sealed credential vault is wired, so the engine refuses to store a key rather than storing one it cannot protect. An administrator must configure the secret sealer.`},next:{title:`Next: deploy an agent`,description:`A credential on its own does not launch anything. Bind it to a provider profile, and a session launched under that profile uses it.`,action:`Go to provider profiles`},truncation:{label:`Showing {{n}} providers; there are more`,hint:"This list is one page. Narrow it, or use `olivares provider ls` for the full set."}},es:{title:`Proveedores`,subtitle:`La credencial con la que arranca una sesión. Regístrala una vez; el motor la sella y se la entrega al agente en el lanzamiento.`,nav:`Proveedores`,add:`Añadir proveedor`,empty:{title:`Todavía no hay ningún proveedor registrado`,description:`Una sesión no puede arrancar sin credencial. Añade la clave de API de Anthropic, OpenAI o xAI —o de cualquier endpoint compatible con OpenAI— y el motor la sella y la usa en el lanzamiento. La clave no se vuelve a mostrar.`,action:`Añade tu primer proveedor`},emptyFiltered:{title:`Ningún proveedor coincide con este filtro`,description:`Quita el filtro para ver todos los proveedores registrados.`,action:`Mostrar todos`},forbidden:{title:`No puedes leer los proveedores de este inquilino`,description:`Leer los proveedores registrados requiere sessions:provider:read. Pídeselo a una administradora de este inquilino.`},columns:{name:`Nombre`,kind:`Tipo`,key:`Clave`,state:`Estado`,connection:`Conexión`},kinds:{anthropic:`Anthropic`,openai:`OpenAI`,xai:`xAI`,openai_compatible:`Compatible con OpenAI`},kindHints:{anthropic:`Claude Code. Inyecta ANTHROPIC_API_KEY.`,openai:`Codex. Inyecta OPENAI_API_KEY.`,xai:`Grok. Inyecta XAI_API_KEY.`,openai_compatible:`Cualquier endpoint con forma de OpenAI. Inyecta OPENAI_API_KEY y OPENAI_BASE_URL; el endpoint es obligatorio.`},states:{active:`Activo`,revoked:`Revocado`},probe:{never:`Sin probar`,ok:`Aceptada`,refused:`Rechazada`,unreachable:`Inalcanzable`,neverHint:`Nadie ha probado esta credencial. Registrarla no es prueba de que funcione.`,okHint:`El proveedor contestó y aceptó esta credencial.`,refusedHint:`El proveedor contestó y rechazó esta credencial. Rótala.`,unreachableHint:`El endpoint no contestó. Esto no dice nada sobre la credencial.`,models:`{{n}} modelos`,latency:`{{ms}} ms`,at:`Probada {{when}}`},actions:{test:`Probar conexión`,testing:`Probando…`,rotate:`Rotar clave`,revoke:`Revocar`,details:`Detalles`},create:{title:`Añadir un proveedor`,description:`El motor sella la clave y no la devuelve nunca. Verás una pista de cuatro caracteres y nada más.`,kind:`Proveedor`,kindPlaceholder:`Elige un proveedor`,name:`Nombre`,nameHint:`Tu propio nombre para esta credencial. Es lo que muestra un selector.`,namePlaceholder:`Anthropic (producción)`,baseURL:`Endpoint`,baseURLHint:`Déjalo vacío para el endpoint oficial del proveedor. Tiene que ser https.`,baseURLPlaceholder:`https://llm.ejemplo.com`,apiKey:`Clave de API`,apiKeyHint:`Se envía una vez, la sella el motor y no vuelve nunca a este navegador.`,apiKeyPlaceholder:`Pega la clave`,submit:`Añadir proveedor`,submitting:`Sellando…`,cancel:`Cancelar`,success:`Proveedor registrado. Prueba la conexión para confirmar que funciona.`,testNext:`Probar la conexión ahora`},rotate:{title:`Rotar la clave de este proveedor`,description:`La clave nueva sustituye a la anterior bajo la misma referencia, así que todos los perfiles vinculados siguen funcionando. Una sesión que ya está corriendo conserva la credencial con la que arrancó.`,verdictCleared:`Se borra la prueba de conexión anterior: un veredicto medido sobre una credencial que ya no existe no es prueba sobre la que la sustituye.`,submit:`Rotar clave`,submitting:`Sellando…`,success:`Clave rotada. Prueba la conexión para confirmar que la nueva funciona.`},revoke:{title:`Revocar este proveedor`,description:`Esto destruye la credencial sellada. No se puede deshacer para esta referencia.`,consequence:`Todos los perfiles de proveedor vinculados se negarán a lanzar, nombrando a este proveedor. La credencial no se revoca en el proveedor: eso se hace en su propia consola.`,confirm:`Revocar`,success:`Proveedor revocado y su credencial sellada destruida.`},detail:{title:`Proveedor`,reference:`Referencia`,endpoint:`Endpoint`,officialEndpoint:`El endpoint oficial del proveedor`,created:`Registrado`,revoked:`Revocado`,models:`Modelos que listó la última prueba`,noModels:`Todavía no hay lista de modelos. Prueba la conexión.`,close:`Cerrar`},vaultUnavailable:{title:`Este despliegue no puede guardar una credencial de proveedor`,description:`No hay ningún almacén sellado de credenciales conectado, así que el motor se niega a guardar una clave en vez de guardar una que no puede proteger. Una administradora tiene que configurar el sellador de secretos.`},next:{title:`Siguiente: despliega un agente`,description:`Una credencial por sí sola no lanza nada. Vincúlala a un perfil de proveedor y una sesión lanzada bajo ese perfil la usará.`,action:`Ir a los perfiles de proveedor`},truncation:{label:`Se muestran {{n}} proveedores; hay más`,hint:"Esta lista es una página. Acótala, o usa `olivares provider ls` para el conjunto completo."}},zh:{title:`提供方`,subtitle:`会话启动时使用的凭据。注册一次即可；引擎会将其封存，并在启动时交给代理。`,nav:`提供方`,add:`添加提供方`,empty:{title:`尚未注册任何提供方`,description:`没有凭据，会话无法启动。添加 Anthropic、OpenAI 或 xAI 的 API 密钥，或任何兼容 OpenAI 的端点的密钥；引擎会将其封存并在启动时使用。密钥不会再次显示。`,action:`添加你的第一个提供方`},emptyFiltered:{title:`没有提供方符合此筛选条件`,description:`清除筛选条件即可查看所有已注册的提供方。`,action:`显示全部`},forbidden:{title:`你无权读取此租户的提供方`,description:`读取已注册的提供方需要 sessions:provider:read。请向该租户的管理员申请。`},columns:{name:`名称`,kind:`类型`,key:`密钥`,state:`状态`,connection:`连接`},kinds:{anthropic:`Anthropic`,openai:`OpenAI`,xai:`xAI`,openai_compatible:`兼容 OpenAI`},kindHints:{anthropic:`Claude Code。注入 ANTHROPIC_API_KEY。`,openai:`Codex。注入 OPENAI_API_KEY。`,xai:`Grok。注入 XAI_API_KEY。`,openai_compatible:`任何 OpenAI 形态的端点。注入 OPENAI_API_KEY 和 OPENAI_BASE_URL；端点为必填。`},states:{active:`有效`,revoked:`已吊销`},probe:{never:`未测试`,ok:`已接受`,refused:`被拒绝`,unreachable:`无法连通`,neverHint:`还没有人测试过这份凭据。注册本身并不能证明它可用。`,okHint:`提供方作出了响应并接受了这份凭据。`,refusedHint:`提供方作出了响应并拒绝了这份凭据。请更换密钥。`,unreachableHint:`端点没有响应。这并不能说明凭据本身有任何问题。`,models:`{{n}} 个模型`,latency:`{{ms}} 毫秒`,at:`测试于 {{when}}`},actions:{test:`测试连接`,testing:`测试中…`,rotate:`更换密钥`,revoke:`吊销`,details:`详情`},create:{title:`添加提供方`,description:`引擎会封存该密钥且永不返回。你只会看到四个字符的提示，再无其他。`,kind:`提供方`,kindPlaceholder:`选择提供方`,name:`名称`,nameHint:`你为这份凭据起的名字。选择器中显示的就是它。`,namePlaceholder:`Anthropic（生产）`,baseURL:`端点`,baseURLHint:`留空表示使用提供方的官方端点。必须是 https。`,baseURLPlaceholder:`https://llm.example.com`,apiKey:`API 密钥`,apiKeyHint:`只发送一次，由引擎封存，永不返回到此浏览器。`,apiKeyPlaceholder:`粘贴密钥`,submit:`添加提供方`,submitting:`封存中…`,cancel:`取消`,success:`提供方已注册。请测试连接以确认它可用。`,testNext:`立即测试连接`},rotate:{title:`更换此提供方的密钥`,description:`新密钥在同一引用下替换旧密钥，因此所有已绑定的配置档案继续可用。已在运行的会话仍保留它启动时的凭据。`,verdictCleared:`先前的连接测试结果会被清除：针对一份已不存在的凭据所得出的结论，并不能证明替换它的那一份可用。`,submit:`更换密钥`,submitting:`封存中…`,success:`密钥已更换。请测试连接以确认新密钥可用。`},revoke:{title:`吊销此提供方`,description:`此操作会销毁已封存的凭据。对该引用而言无法撤销。`,consequence:`所有绑定到它的提供方配置档案都将拒绝启动，并指名这个提供方。提供方那一侧的凭据不会被吊销：请在他们自己的控制台中操作。`,confirm:`吊销`,success:`提供方已吊销，其封存的凭据已被销毁。`},detail:{title:`提供方`,reference:`引用`,endpoint:`端点`,officialEndpoint:`提供方的官方端点`,created:`注册于`,revoked:`吊销于`,models:`最近一次测试列出的模型`,noModels:`尚无模型列表。请测试连接。`,close:`关闭`},vaultUnavailable:{title:`此部署无法保存提供方凭据`,description:`没有接入封存式凭据保管库，因此引擎拒绝保存密钥，而不是保存一份它无法保护的密钥。需要管理员配置机密封存器。`},next:{title:`下一步：部署一个代理`,description:`仅有凭据不会启动任何东西。把它绑定到提供方配置档案，在该档案下启动的会话就会使用它。`,action:`前往提供方配置档案`},truncation:{label:`正在显示 {{n}} 个提供方；还有更多`,hint:"此列表只是一页。请缩小范围，或使用 `olivares provider ls` 获取完整集合。"}},ja:{title:`プロバイダー`,subtitle:`セッションが起動するときに使う資格情報です。一度登録すれば、エンジンが封印し、起動時にエージェントへ渡します。`,nav:`プロバイダー`,add:`プロバイダーを追加`,empty:{title:`まだプロバイダーが登録されていません`,description:`資格情報がなければセッションは起動できません。Anthropic、OpenAI、xAI の API キー、または OpenAI 互換のエンドポイントのキーを追加してください。エンジンがそれを封印し、起動時に使用します。キーは二度と表示されません。`,action:`最初のプロバイダーを追加`},emptyFiltered:{title:`この絞り込みに一致するプロバイダーはありません`,description:`絞り込みを解除すると、登録済みのすべてのプロバイダーが表示されます。`,action:`すべて表示`},forbidden:{title:`このテナントのプロバイダーを読み取る権限がありません`,description:`登録済みプロバイダーの読み取りには sessions:provider:read が必要です。このテナントの管理者に依頼してください。`},columns:{name:`名前`,kind:`種類`,key:`キー`,state:`状態`,connection:`接続`},kinds:{anthropic:`Anthropic`,openai:`OpenAI`,xai:`xAI`,openai_compatible:`OpenAI 互換`},kindHints:{anthropic:`Claude Code。ANTHROPIC_API_KEY を注入します。`,openai:`Codex。OPENAI_API_KEY を注入します。`,xai:`Grok。XAI_API_KEY を注入します。`,openai_compatible:`OpenAI 形式の任意のエンドポイント。OPENAI_API_KEY と OPENAI_BASE_URL を注入します。エンドポイントは必須です。`},states:{active:`有効`,revoked:`失効`},probe:{never:`未テスト`,ok:`受理`,refused:`拒否`,unreachable:`到達不能`,neverHint:`この資格情報はまだ誰もテストしていません。登録しただけでは動作の証拠になりません。`,okHint:`プロバイダーが応答し、この資格情報を受理しました。`,refusedHint:`プロバイダーが応答し、この資格情報を拒否しました。キーを交換してください。`,unreachableHint:`エンドポイントが応答しませんでした。これは資格情報については何も示しません。`,models:`{{n}} 個のモデル`,latency:`{{ms}} ミリ秒`,at:`テスト日時 {{when}}`},actions:{test:`接続をテスト`,testing:`テスト中…`,rotate:`キーを交換`,revoke:`失効させる`,details:`詳細`},create:{title:`プロバイダーを追加`,description:`エンジンがキーを封印し、二度と返しません。表示されるのは 4 文字のヒントだけです。`,kind:`プロバイダー`,kindPlaceholder:`プロバイダーを選択`,name:`名前`,nameHint:`この資格情報に付けるあなた自身の名前です。選択肢にはこれが表示されます。`,namePlaceholder:`Anthropic（本番）`,baseURL:`エンドポイント`,baseURLHint:`空のままにするとプロバイダーの公式エンドポイントを使います。https である必要があります。`,baseURLPlaceholder:`https://llm.example.com`,apiKey:`API キー`,apiKeyHint:`一度だけ送信され、エンジンが封印し、このブラウザーには二度と返されません。`,apiKeyPlaceholder:`キーを貼り付け`,submit:`プロバイダーを追加`,submitting:`封印中…`,cancel:`キャンセル`,success:`プロバイダーを登録しました。接続をテストして動作を確認してください。`,testNext:`今すぐ接続をテスト`},rotate:{title:`このプロバイダーのキーを交換`,description:`新しいキーが同じ参照の下で古いキーを置き換えるので、紐づいたすべてのプロファイルはそのまま動きます。実行中のセッションは起動時の資格情報を保持します。`,verdictCleared:`以前の接続テスト結果は消去されます。すでに存在しない資格情報について測った判定は、それを置き換えた資格情報の証拠にはなりません。`,submit:`キーを交換`,submitting:`封印中…`,success:`キーを交換しました。接続をテストして新しいキーを確認してください。`},revoke:{title:`このプロバイダーを失効させる`,description:`封印された資格情報を破棄します。この参照については元に戻せません。`,consequence:`紐づいたすべてのプロバイダープロファイルは、このプロバイダーの名前を挙げて起動を拒否します。プロバイダー側では失効しません。それは各社のコンソールで行ってください。`,confirm:`失効させる`,success:`プロバイダーを失効させ、封印された資格情報を破棄しました。`},detail:{title:`プロバイダー`,reference:`参照`,endpoint:`エンドポイント`,officialEndpoint:`プロバイダーの公式エンドポイント`,created:`登録日時`,revoked:`失効日時`,models:`直近のテストが列挙したモデル`,noModels:`まだモデル一覧がありません。接続をテストしてください。`,close:`閉じる`},vaultUnavailable:{title:`この配備ではプロバイダーの資格情報を保存できません`,description:`封印された資格情報保管庫が接続されていないため、エンジンは保護できないキーを保存する代わりに、保存を拒否します。管理者がシークレット封印器を設定する必要があります。`},next:{title:`次は、エージェントを配備します`,description:`資格情報だけでは何も起動しません。プロバイダープロファイルに紐づけると、そのプロファイルで起動したセッションがそれを使います。`,action:`プロバイダープロファイルへ`},truncation:{label:`{{n}} 件のプロバイダーを表示中。さらにあります`,hint:"この一覧は 1 ページです。絞り込むか、`olivares provider ls` で全件を確認してください。"}},de:{title:`Anbieter`,subtitle:`Die Zugangsdaten, mit denen eine Sitzung startet. Einmal registrieren; die Engine versiegelt sie und übergibt sie dem Agenten beim Start.`,nav:`Anbieter`,add:`Anbieter hinzufügen`,empty:{title:`Noch kein Anbieter registriert`,description:`Ohne Zugangsdaten kann keine Sitzung starten. Fügen Sie den API-Schlüssel von Anthropic, OpenAI oder xAI hinzu — oder von einem beliebigen OpenAI-kompatiblen Endpunkt — und die Engine versiegelt ihn und verwendet ihn beim Start. Der Schlüssel wird nie wieder angezeigt.`,action:`Ersten Anbieter hinzufügen`},emptyFiltered:{title:`Kein Anbieter passt zu diesem Filter`,description:`Entfernen Sie den Filter, um alle registrierten Anbieter zu sehen.`,action:`Alle anzeigen`},forbidden:{title:`Sie dürfen die Anbieter dieses Mandanten nicht lesen`,description:`Das Lesen registrierter Anbieter erfordert sessions:provider:read. Bitten Sie eine Administratorin dieses Mandanten darum.`},columns:{name:`Name`,kind:`Art`,key:`Schlüssel`,state:`Zustand`,connection:`Verbindung`},kinds:{anthropic:`Anthropic`,openai:`OpenAI`,xai:`xAI`,openai_compatible:`OpenAI-kompatibel`},kindHints:{anthropic:`Claude Code. Setzt ANTHROPIC_API_KEY.`,openai:`Codex. Setzt OPENAI_API_KEY.`,xai:`Grok. Setzt XAI_API_KEY.`,openai_compatible:`Jeder Endpunkt in OpenAI-Form. Setzt OPENAI_API_KEY und OPENAI_BASE_URL; der Endpunkt ist erforderlich.`},states:{active:`Aktiv`,revoked:`Widerrufen`},probe:{never:`Nicht getestet`,ok:`Akzeptiert`,refused:`Abgelehnt`,unreachable:`Nicht erreichbar`,neverHint:`Niemand hat diese Zugangsdaten getestet. Sie zu registrieren ist kein Beleg dafür, dass sie funktionieren.`,okHint:`Der Anbieter hat geantwortet und diese Zugangsdaten akzeptiert.`,refusedHint:`Der Anbieter hat geantwortet und diese Zugangsdaten abgelehnt. Wechseln Sie den Schlüssel.`,unreachableHint:`Der Endpunkt hat nicht geantwortet. Das sagt nichts über die Zugangsdaten aus.`,models:`{{n}} Modelle`,latency:`{{ms}} ms`,at:`Getestet {{when}}`},actions:{test:`Verbindung testen`,testing:`Wird getestet…`,rotate:`Schlüssel wechseln`,revoke:`Widerrufen`,details:`Details`},create:{title:`Anbieter hinzufügen`,description:`Die Engine versiegelt den Schlüssel und gibt ihn nie zurück. Sie sehen einen Hinweis aus vier Zeichen und sonst nichts.`,kind:`Anbieter`,kindPlaceholder:`Anbieter wählen`,name:`Name`,nameHint:`Ihr eigener Name für diese Zugangsdaten. Das zeigt eine Auswahl an.`,namePlaceholder:`Anthropic (Produktion)`,baseURL:`Endpunkt`,baseURLHint:`Leer lassen für den offiziellen Endpunkt des Anbieters. Muss https sein.`,baseURLPlaceholder:`https://llm.beispiel.de`,apiKey:`API-Schlüssel`,apiKeyHint:`Einmal gesendet, von der Engine versiegelt, nie an diesen Browser zurückgegeben.`,apiKeyPlaceholder:`Schlüssel einfügen`,submit:`Anbieter hinzufügen`,submitting:`Wird versiegelt…`,cancel:`Abbrechen`,success:`Anbieter registriert. Testen Sie die Verbindung, um zu bestätigen, dass er funktioniert.`,testNext:`Verbindung jetzt testen`},rotate:{title:`Schlüssel dieses Anbieters wechseln`,description:`Der neue Schlüssel ersetzt den alten unter derselben Referenz, also funktionieren alle gebundenen Profile weiter. Eine bereits laufende Sitzung behält die Zugangsdaten, mit denen sie gestartet ist.`,verdictCleared:`Der vorherige Verbindungstest wird gelöscht: ein Urteil über Zugangsdaten, die es nicht mehr gibt, belegt nichts über die, die sie ersetzen.`,submit:`Schlüssel wechseln`,submitting:`Wird versiegelt…`,success:`Schlüssel gewechselt. Testen Sie die Verbindung, um den neuen zu bestätigen.`},revoke:{title:`Diesen Anbieter widerrufen`,description:`Das zerstört die versiegelten Zugangsdaten. Für diese Referenz ist es nicht rückgängig zu machen.`,consequence:`Jedes daran gebundene Anbieterprofil verweigert den Start und nennt diesen Anbieter. Beim Anbieter selbst werden die Zugangsdaten nicht widerrufen: das tun Sie in dessen eigener Konsole.`,confirm:`Widerrufen`,success:`Anbieter widerrufen und seine versiegelten Zugangsdaten zerstört.`},detail:{title:`Anbieter`,reference:`Referenz`,endpoint:`Endpunkt`,officialEndpoint:`Der offizielle Endpunkt des Anbieters`,created:`Registriert`,revoked:`Widerrufen`,models:`Modelle, die der letzte Test aufgelistet hat`,noModels:`Noch keine Modellliste. Testen Sie die Verbindung.`,close:`Schließen`},vaultUnavailable:{title:`Diese Installation kann keine Anbieter-Zugangsdaten speichern`,description:`Es ist kein versiegelter Tresor verdrahtet, daher verweigert die Engine das Speichern eines Schlüssels, statt einen zu speichern, den sie nicht schützen kann. Eine Administratorin muss den Secret-Sealer konfigurieren.`},next:{title:`Als Nächstes: einen Agenten bereitstellen`,description:`Zugangsdaten allein starten nichts. Binden Sie sie an ein Anbieterprofil, dann verwendet sie eine unter diesem Profil gestartete Sitzung.`,action:`Zu den Anbieterprofilen`},truncation:{label:`{{n}} Anbieter angezeigt; es gibt mehr`,hint:"Diese Liste ist eine Seite. Grenzen Sie sie ein, oder nutzen Sie `olivares provider ls` für den vollständigen Satz."}},ru:{title:`Провайдеры`,subtitle:`Учётные данные, с которыми запускается сессия. Зарегистрируйте один раз; движок запечатает их и передаст агенту при запуске.`,nav:`Провайдеры`,add:`Добавить провайдера`,empty:{title:`Пока не зарегистрирован ни один провайдер`,description:`Без учётных данных сессия не запустится. Добавьте API-ключ Anthropic, OpenAI или xAI — либо любой OpenAI-совместимой конечной точки — и движок запечатает его и использует при запуске. Ключ больше никогда не показывается.`,action:`Добавьте первого провайдера`},emptyFiltered:{title:`Под этот фильтр не подходит ни один провайдер`,description:`Снимите фильтр, чтобы увидеть всех зарегистрированных провайдеров.`,action:`Показать всех`},forbidden:{title:`Вам нельзя читать провайдеров этого арендатора`,description:`Чтение зарегистрированных провайдеров требует sessions:provider:read. Попросите об этом администратора этого арендатора.`},columns:{name:`Имя`,kind:`Вид`,key:`Ключ`,state:`Состояние`,connection:`Соединение`},kinds:{anthropic:`Anthropic`,openai:`OpenAI`,xai:`xAI`,openai_compatible:`OpenAI-совместимый`},kindHints:{anthropic:`Claude Code. Внедряет ANTHROPIC_API_KEY.`,openai:`Codex. Внедряет OPENAI_API_KEY.`,xai:`Grok. Внедряет XAI_API_KEY.`,openai_compatible:`Любая конечная точка в форме OpenAI. Внедряет OPENAI_API_KEY и OPENAI_BASE_URL; конечная точка обязательна.`},states:{active:`Активен`,revoked:`Отозван`},probe:{never:`Не проверен`,ok:`Принят`,refused:`Отклонён`,unreachable:`Недоступен`,neverHint:`Эти учётные данные никто не проверял. Регистрация не является доказательством того, что они работают.`,okHint:`Провайдер ответил и принял эти учётные данные.`,refusedHint:`Провайдер ответил и отклонил эти учётные данные. Замените ключ.`,unreachableHint:`Конечная точка не ответила. Это ничего не говорит об учётных данных.`,models:`{{n}} моделей`,latency:`{{ms}} мс`,at:`Проверено {{when}}`},actions:{test:`Проверить соединение`,testing:`Проверка…`,rotate:`Заменить ключ`,revoke:`Отозвать`,details:`Подробности`},create:{title:`Добавить провайдера`,description:`Движок запечатывает ключ и никогда его не возвращает. Вы увидите подсказку из четырёх символов и ничего больше.`,kind:`Провайдер`,kindPlaceholder:`Выберите провайдера`,name:`Имя`,nameHint:`Ваше собственное имя для этих учётных данных. Именно его показывает список выбора.`,namePlaceholder:`Anthropic (продакшен)`,baseURL:`Конечная точка`,baseURLHint:`Оставьте пустым для официальной конечной точки провайдера. Должна быть https.`,baseURLPlaceholder:`https://llm.example.com`,apiKey:`API-ключ`,apiKeyHint:`Отправляется один раз, запечатывается движком и никогда не возвращается в этот браузер.`,apiKeyPlaceholder:`Вставьте ключ`,submit:`Добавить провайдера`,submitting:`Запечатывание…`,cancel:`Отмена`,success:`Провайдер зарегистрирован. Проверьте соединение, чтобы убедиться, что он работает.`,testNext:`Проверить соединение сейчас`},rotate:{title:`Заменить ключ этого провайдера`,description:`Новый ключ заменяет прежний под той же ссылкой, поэтому все привязанные профили продолжают работать. Уже идущая сессия сохраняет учётные данные, с которыми она запустилась.`,verdictCleared:`Прежний результат проверки стирается: вердикт, измеренный для учётных данных, которых больше нет, ничего не доказывает о тех, что их заменили.`,submit:`Заменить ключ`,submitting:`Запечатывание…`,success:`Ключ заменён. Проверьте соединение, чтобы убедиться, что новый работает.`},revoke:{title:`Отозвать этого провайдера`,description:`Это уничтожает запечатанные учётные данные. Для этой ссылки отменить нельзя.`,consequence:`Каждый привязанный профиль провайдера откажется запускаться, назвав этого провайдера. У самого провайдера учётные данные не отзываются: сделайте это в его собственной консоли.`,confirm:`Отозвать`,success:`Провайдер отозван, его запечатанные учётные данные уничтожены.`},detail:{title:`Провайдер`,reference:`Ссылка`,endpoint:`Конечная точка`,officialEndpoint:`Официальная конечная точка провайдера`,created:`Зарегистрирован`,revoked:`Отозван`,models:`Модели, перечисленные последней проверкой`,noModels:`Списка моделей пока нет. Проверьте соединение.`,close:`Закрыть`},vaultUnavailable:{title:`Это развёртывание не может хранить учётные данные провайдера`,description:`Запечатанное хранилище не подключено, поэтому движок отказывается сохранить ключ вместо того, чтобы хранить тот, который он не может защитить. Администратор должен настроить запечатыватель секретов.`},next:{title:`Далее: разверните агента`,description:`Сами по себе учётные данные ничего не запускают. Привяжите их к профилю провайдера, и сессия, запущенная под этим профилем, будет их использовать.`,action:`Перейти к профилям провайдеров`},truncation:{label:`Показано провайдеров: {{n}}; есть ещё`,hint:"Этот список — одна страница. Сузьте его или используйте `olivares provider ls` для полного набора."}},fr:{title:`Fournisseurs`,subtitle:`L'identifiant avec lequel une session démarre. Enregistrez-le une fois ; le moteur le scelle et le remet à l'agent au lancement.`,nav:`Fournisseurs`,add:`Ajouter un fournisseur`,empty:{title:`Aucun fournisseur enregistré pour l'instant`,description:`Une session ne peut pas démarrer sans identifiant. Ajoutez la clé d'API d'Anthropic, d'OpenAI ou de xAI — ou de tout point de terminaison compatible OpenAI — et le moteur la scelle et l'utilise au lancement. La clé n'est plus jamais affichée.`,action:`Ajoutez votre premier fournisseur`},emptyFiltered:{title:`Aucun fournisseur ne correspond à ce filtre`,description:`Retirez le filtre pour voir tous les fournisseurs enregistrés.`,action:`Tout afficher`},forbidden:{title:`Vous ne pouvez pas lire les fournisseurs de ce locataire`,description:`Lire les fournisseurs enregistrés demande sessions:provider:read. Demandez-le à une personne administratrice de ce locataire.`},columns:{name:`Nom`,kind:`Type`,key:`Clé`,state:`État`,connection:`Connexion`},kinds:{anthropic:`Anthropic`,openai:`OpenAI`,xai:`xAI`,openai_compatible:`Compatible OpenAI`},kindHints:{anthropic:`Claude Code. Injecte ANTHROPIC_API_KEY.`,openai:`Codex. Injecte OPENAI_API_KEY.`,xai:`Grok. Injecte XAI_API_KEY.`,openai_compatible:`Tout point de terminaison de forme OpenAI. Injecte OPENAI_API_KEY et OPENAI_BASE_URL ; le point de terminaison est obligatoire.`},states:{active:`Actif`,revoked:`Révoqué`},probe:{never:`Non testé`,ok:`Acceptée`,refused:`Refusée`,unreachable:`Injoignable`,neverHint:`Personne n'a testé cet identifiant. L'enregistrer ne prouve pas qu'il fonctionne.`,okHint:`Le fournisseur a répondu et a accepté cet identifiant.`,refusedHint:`Le fournisseur a répondu et a rejeté cet identifiant. Faites-le tourner.`,unreachableHint:`Le point de terminaison n'a pas répondu. Cela ne dit rien sur l'identifiant.`,models:`{{n}} modèles`,latency:`{{ms}} ms`,at:`Testé {{when}}`},actions:{test:`Tester la connexion`,testing:`Test en cours…`,rotate:`Changer la clé`,revoke:`Révoquer`,details:`Détails`},create:{title:`Ajouter un fournisseur`,description:`Le moteur scelle la clé et ne la renvoie jamais. Vous verrez un indice de quatre caractères, rien de plus.`,kind:`Fournisseur`,kindPlaceholder:`Choisissez un fournisseur`,name:`Nom`,nameHint:`Votre propre nom pour cet identifiant. C'est ce qu'affiche un sélecteur.`,namePlaceholder:`Anthropic (production)`,baseURL:`Point de terminaison`,baseURLHint:`Laissez vide pour le point de terminaison officiel du fournisseur. Doit être en https.`,baseURLPlaceholder:`https://llm.exemple.com`,apiKey:`Clé d'API`,apiKeyHint:`Envoyée une fois, scellée par le moteur, jamais renvoyée à ce navigateur.`,apiKeyPlaceholder:`Collez la clé`,submit:`Ajouter le fournisseur`,submitting:`Scellement…`,cancel:`Annuler`,success:`Fournisseur enregistré. Testez la connexion pour confirmer qu'il fonctionne.`,testNext:`Tester la connexion maintenant`},rotate:{title:`Changer la clé de ce fournisseur`,description:`La nouvelle clé remplace l'ancienne sous la même référence, donc tous les profils qui y sont liés continuent de fonctionner. Une session déjà en cours garde l'identifiant avec lequel elle a démarré.`,verdictCleared:`Le test de connexion précédent est effacé : un verdict mesuré sur un identifiant qui n'existe plus ne prouve rien sur celui qui le remplace.`,submit:`Changer la clé`,submitting:`Scellement…`,success:`Clé changée. Testez la connexion pour confirmer que la nouvelle fonctionne.`},revoke:{title:`Révoquer ce fournisseur`,description:`Cela détruit l'identifiant scellé. C'est irréversible pour cette référence.`,consequence:`Tous les profils de fournisseur liés refuseront de lancer, en nommant ce fournisseur. L'identifiant n'est pas révoqué chez le fournisseur : faites-le dans sa propre console.`,confirm:`Révoquer`,success:`Fournisseur révoqué et son identifiant scellé détruit.`},detail:{title:`Fournisseur`,reference:`Référence`,endpoint:`Point de terminaison`,officialEndpoint:`Le point de terminaison officiel du fournisseur`,created:`Enregistré`,revoked:`Révoqué`,models:`Modèles listés par le dernier test`,noModels:`Pas encore de liste de modèles. Testez la connexion.`,close:`Fermer`},vaultUnavailable:{title:`Ce déploiement ne peut pas stocker un identifiant de fournisseur`,description:`Aucun coffre scellé n'est câblé, donc le moteur refuse de stocker une clé plutôt que d'en stocker une qu'il ne peut pas protéger. Une personne administratrice doit configurer le scelleur de secrets.`},next:{title:`Ensuite : déployez un agent`,description:`Un identifiant seul ne lance rien. Liez-le à un profil de fournisseur, et une session lancée sous ce profil l'utilisera.`,action:`Aller aux profils de fournisseur`},truncation:{label:`{{n}} fournisseurs affichés ; il y en a d’autres`,hint:"Cette liste est une page. Affinez-la, ou utilisez `olivares provider ls` pour l’ensemble complet."}}});var E=`/v1/m/sessions/providers`,D=e=>enc